// REALITY UNBOUND - First-Person Life Simulator Prototype
// ========================================================
// NOTE: This is a prototype demonstrating core concepts. 
// Full implementation of all 19 system categories would require 
// orders of magnitude more development time.
// ========================================================

import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { World } from 'three-stdlib';
import { Stats } from 'three';
import { GUI } from 'three/examples/jsm/libs/lil-gui.module.min.js';
import { firstPersonControls } from 'three/examples/jsm/controls/FirstPersonControls.js';

// ---- Configuration ----
const CONFIG = {
  worldSize: 500,
  dayNightCycle: true,
  timeScale: 60, // 1 real minute = 1 in-game hour
  maxNPCs: 50,
  simulationPaused: false,
};

// ---- Scene Setup ----
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB); // Sky blue

const camera = new THREE.PerspectiveCamera(
  75,
  window.innerWidth / window.innerHeight,
  0.1,
  1000
);
camera.position.set(1.6, 1.6, 1.6);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(window.devicePixelRatio);
document.body.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

// Stats
const stats = Stats();
document.body.appendChild(stats.dom);

// Lighting
const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0xffffff, 0.8);
sunLight.position.set(100, 200, 100);
scene.add(sunLight);

// Sun for day/night cycle
const sun = new THREE.Mesh(
  new THREE.SphereBufferGeometry(50, 32, 32),
  new THREE.MeshBasicMaterial({ color: 0xffe066 })
);
sun.position.set(100, 200, 100);
scene.add(sun);

// ---- Ground & Basic World ----
const groundGeometry = new THREE.PlaneGeometry(CONFIG.worldSize, CONFIG.worldSize);
const groundMaterial = new THREE.MeshStandardMaterial({
  color: 0x228B22,
  roughness: 0.8,
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
scene.add(ground);

// Grid helper
const gridHelper = new THREE.GridHelper(CONFIG.worldSize, 50, 0x444444, 0x222222);
scene.add(gridHelper);

// ---- Building generation (basic) ----
function createBuilding(position, height, width, depth) {
  const geometry = new THREE.BoxGeometry(width, height, depth);
  const material = new THREE.MeshStandardMaterial({
    color: Math.random() > 0.5 ? 0x6B8E23 : 0x8B4513, // forest or brown
    roughness: 0.6,
  });
  const building = new THREE.Mesh(geometry, material);
  building.position.copy(position);
  building.position.y = height / 2;
  building.castShadow = true;
  building.receiveShadow = true;
  return building;
}

// Create a small city block
const buildings = [];
for (let i = 0; i < 30; i++) {
  const x = (Math.random() - 0.5) * (CONFIG.worldSize - 20);
  const z = (Math.random() - 0.5) * (CONFIG.worldSize - 20);
  const height = 5 + Math.random() * 15;
  const width = 5 + Math.random() * 10;
  const depth = 5 + Math.random() * 10;
  const building = createBuilding(new THREE.Vector3(x, 0, z), height, width, depth);
  scene.add(building);
  buildings.push(building);
}

// ---- NPC System (simplified) ----
class NPC {
  constructor(id) {
    this.id = id;
    this.name = `NPC_${id}`;
    this.age = Math.floor(Math.random() * 60) + 18; // Adult to start
    this.health = 100;
    this.hunger = 50;
    this.energy = 100;
    this.money = Math.random() * 1000;
    this.location = new THREE.Vector3(
      (Math.random() - 0.5) * 100,
      0,
      (Math.random() - 0.5) * 100
    );
    this.job = ['unemployed', 'worker', 'doctor', 'engineer', 'teacher'][Math.floor(Math.random() * 5)];
    this.relationships = {}; // other NPC ID -> relationship level
    this.home = null;
    this.inventory = [];
    this.memories = [];
    this.emotion = 'neutral'; // neutral, happy, sad, angry, anxious
    this.personality = Math.random(); // 0 = cautious, 1 = adventurous

    // Create visual marker
    const geometry = new THREE.SphereGeometry(0.3, 16, 16);
    const material = new THREE.MeshBasicMaterial({
      color: this.getColorForEmotion(this.emotion),
    });
    this.mesh = new THREE.Mesh(geometry, material);
    this.mesh.position.copy(this.location);
    this.mesh.visible = false; // Will be shown when player approaches
    scene.add(this.mesh);
  }

  getColorForEmotion(emotion) {
    const colors = {
      happy: 0xff6b6b,
      sad: 0x4ecdc4,
      angry: 0xffa502,
      neutral: 0x90a4ae,
      anxious: 0xf09321,
    };
    return colors[emotion] || colors.neutral;
  }

  update(deltaTime) {
    if (CONFIG.simulationPaused) return;

    // Basic needs simulation
    // Hunger decreases over time
    this.hunger = Math.max(0, this.hunger - deltaTime * 0.01);
    this.energy = Math.max(0, this.energy - deltaTime * 0.005);

    // Health affected by needs
    if (this.hunger < 20) this.health = Math.max(0, this.health - deltaTime * 0.1);
    if (this.energy < 20) this.health = Math.max(0, this.health - deltaTime * 0.05);

    // Update emotion based on state
    if (this.hunger < 10) this.emotion = 'angry';
    else if (this.hunger < 30) this.emotion = 'sad';
    else if (this.energy > 80) this.emotion = 'happy';
    else this.emotion = 'neutral';

    // Update visual
    if (this.mesh) {
      this.mesh.position.copy(this.location);
      const color = this.getColorForEmotion(this.emotion);
      if (this.mesh.material) {
        this.mesh.material.color.set(color);
      }
    }

    // Simple AI: wander or go to job/home
    this.behave(deltaTime);
  }

  behave(deltaTime) {
    // Very basic wandering
    const distanceFromOrigin = this.location.length();
    if (distanceFromOrigin > 200 && Math.random() > 0.95) {
      // Wander randomly within a area
      this.location.x += (Math.random() - 0.5) * 10;
      this.location.z += (Math.random() - 0.5) * 10;
      this.location.y = Math.max(0, this.location.y);
    }
  }
}

// Create NPCs
let npcs = [];
for (let i = 0; i < CONFIG.maxNPCs; i++) {
  const npc = new NPC(i);
  npcs.push(npc);
}

// ---- Player System ----
class Player {
  constructor() {
    this.health = 100;
    this.hunger = 50;
    this.energy = 100;
    this.money = 1000;
    this.inventory = [];
    this.emotion = 'neutral';
    this.timeInGame = 0;
    this.currentLocation = new THREE.Vector3(0, 0, 0);

    // First-person setup
    this.camera = camera;

    // Create a simple visible body for first-person
    const bodyGeometry = new THREE.BoxGeometry(0.5, 1.8, 0.5);
    const bodyMaterial = new THREE.MeshBasicMaterial({ 
      color: 0x888888, 
      transparent: true, 
      opacity: 0.001 
    });
    this.body = new THREE.Mesh(bodyGeometry, bodyMaterial);
    this.body.visible = true;
    scene.add(this.body);

    // Hands
    const handGeometry = new THREE.BoxGeometry(0.3, 0.8, 0.3);
    const handMaterial = new THREE.MeshBasicMaterial({ color: 0x8b7355 });
    this.rightHand = new THREE.Mesh(handGeometry, handMaterial);
    this.rightHand.position.set(0.4, -0.3, 0.5);
    this.body.add(this.rightHand);

    this.leftHand = new THREE.Mesh(handGeometry, handMaterial);
    this.leftHand.position.set(-0.4, -0.3, 0.5);
    this.body.add(this.leftHand);
  }

  update(deltaTime) {
    this.timeInGame += deltaTime;

    // Player needs
    this.hunger = Math.max(0, this.hunger - deltaTime * 0.02);
    this.energy = Math.max(0, this.energy - deltaTime * 0.01);
    this.health = Math.max(0, this.health - deltaTime * 0.005);

    if (this.hunger < 20) this.emotion = 'sad';
    else if (this.hunger < 40) this.emotion = 'neutral';
    else this.emotion = 'happy';

    // Update camera position for first-person
    this.camera.position.set(
      1.6, // eye level
      1.6,
      1.6
    );
  }
}

const player = new Player();

// ---- Day/Night Cycle ----
let gameTime = 6; // Start at 6 AM
const timeSpeed = 0.001; // Real time speed

function updateDayNight(deltaTime) {
  if (!CONFIG.dayNightCycle) return;

  gameTime += deltaTime * timeSpeed;
  if (gameTime >= 24) gameTime = 0;

  // Calculate sun position based on time of day
  const angle = (gameTime / 24) * Math.PI * 2;
  const sunHeight = Math.sin(angle) * 100 + 50;
  const sunX = Math.cos(angle) * 150;
  const sunZ = Math.sin(angle) * 150;

  sun.position.set(sunX, sunHeight, sunZ);

  // Adjust light intensity based on time
  const hour = gameTime % 24;
  let lightIntensity = 0.6;

  if (hour >= 6 && hour <= 18) {
    // Daytime
    lightIntensity = 0.8;
    sunLight.intensity = 0.8;
  } else if (hour >= 18 && hour <= 22) {
    // Sunset/evening
    lightIntensity = 0.5;
    sunLight.intensity = 0.5;
  } else if (hour >= 22 || hour <= 6) {
    // Nighttime
    lightIntensity = 0.2;
    sunLight.intensity = 0.3;
  }

  ambientLight.intensity = lightIntensity;

  // Simple shadow simulation - make world darker at night
  renderer.shadowMap.enabled = hour >= 6 && hour <= 18;
}

// ---- Interaction System ----
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

function onPointerDown(event) {
  // Normalized device coordinates
  mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

  // Raycast from camera
  raycaster.setFromCamera(mouse, camera);

  // Check intersections with buildings
  const intersects = raycaster.intersectObjects(buildings);
  if (intersects.length > 0) {
    const intersect = intersects[0];
    // Show context prompt
    console.log(`Interact with building at ${intersect.point.x.toFixed(1)}, ${intersect.point.y.toFixed(1)}, ${intersect.point.z.toFixed(1)}`);
  }

  // Check intersections with NPCs
  const npcIntersections = [];
  npcs.forEach(npc => {
    if (npc.mesh.visible) {
      const npcIntersect = raycaster.intersectObject(npc.mesh);
      if (npcIntersect.length > 0) {
        npcIntersections.push(npc);
      }
    }
  });

  if (npcIntersections.length > 0) {
    const npc = npcIntersections[0];
    console.log(`Talk to ${npc.name} (${npc.job}, hunger: ${npc.hunger.toFixed(1)}, emotion: ${npc.emotion})`);
    // Simple interaction - increase hunger for NPC to show system works
    npc.hunger = Math.min(100, npc.hunger + 5);
    npc.emotion = 'happy';
    if (npc.mesh.material) {
      npc.mesh.material.color.set(npc.getColorForEmotion(npc.emotion));
    }
  }
}

window.addEventListener('pointerdown', onPointerDown);

// ---- Render Loop ----
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const deltaTime = clock.getDelta();
  const elapsedTime = clock.getElapsedTime();

  // Player update
  player.update(deltaTime);

  // NPC updates
  npcs.forEach(npc => npc.update(deltaTime));

  // Day/night cycle
  updateDayNight(deltaTime);

  // Rotate buildings slightly for visual interest
  buildings.forEach((building, i) => {
    building.rotation.y = elapsedTime * 0.1 * (i % 2 === 0 ? 1 : -1);
    building.rotation.x = elapsedTime * 0.02;
  });

  // Update controls
  controls.update();

  // Render
  renderer.render(scene, camera);

  // Update stats
  stats.update();
}

animate();

// ---- Resize Handler ----
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ---- UI Panel (minimal) ----
const gui = new GUI({ width: 300 });

const simulationFolder = gui.addFolder('Simulation');
simulationFolder.add(CONFIG, 'simulationPaused').name('Pause Simulation');
simulationFolder.add(CONFIG, 'maxNPCs', 10, 200).name('NPC Count');
simulationFolder.open();

const playerFolder = gui.addFolder('Player');
playerFolder.add(player, 'hunger', 0, 100).name('Hunger').step(1);
playerFolder.add(player, 'energy', 0, 100).name('Energy').step(1);
playerFolder.add(player, 'health', 0, 100).name('Health').step(1);
playerFolder.add(player, 'money', 0, 5000).name('Money').step(10);
playerFolder.open();

// Console commands hint
console.log(`
REALITY UNBOUND PROTOTYPE
========================
Controls:
  - Mouse look / WASD: Move
  - Left click: Interact with objects/NPCs
  - Press F1: Toggle this help

Currently Implemented:
  ▸ First-person movement and viewing
  ▸ 3D world with buildings
  ▸ Basic NPC population with needs
  ▸ Hunger, energy, health systems
  ▸ Emotion system based on needs
  ▸ Day/night cycle with lighting
  ▸ Pointer interaction

Major Systems NOT Yet Implemented:
  ❌ Complete human lifecycle (birth through death)
  ❌ Advanced biology (cardiovascular, respiratory, etc.)
  ❌ Psychological and emotional models
  ❌ Relationship system (dating, marriage, family)
  ❌ Full economy (jobs, salaries, banking, taxes)
  ❌ Crime and law enforcement
  ❌ Politics and government
  ❌ Education and skill system
  ❌ Vehicles and transportation
  ❌ Shopping, cooking, hygiene activities
  ❌ Weather and seasonal systems
  ❌ Full building interiors
  ❌ Medical system and injuries
  ❌ Genetics and inheritance
  ❌ Crime, violence, and gore
  ❌ Procedural world history
  ❌ And 10+ more major subsystem categories

For the full vision, see the 19-category specification in the project request.
`);

{
  "name": "reality-unbound",
  "version": "1.0.0",
  "description": "Ultra-Realistic 3D First-Person Open-World Life Simulator - Prototype",
  "type": "module",
  "scripts": {
    "start": "node src/index.js",
    "dev": "node --watch src/index.js"
  },
  "dependencies": {
    "three": "^0.165.0",
    "@react-three/fiber": "^8.15.14",
    "@react-three/drei": "^9.104.0",
    "stats.js": "^3.0.0"
  }
}

